import type { MetadataRoute } from 'next';

// PWA manifest for ArixCall. Next serves this at /manifest.webmanifest and
// injects <link rel="manifest"> site-wide. Icons live in /public (generated by
// scripts/gen-arix-icons.mjs).
export default function manifest(): MetadataRoute.Manifest {
  return {
    name: 'ArixCall',
    short_name: 'ArixCall',
    description: 'ArixCall — Connect · Communicate · Convert',
    start_url: '/phone',
    display: 'standalone',
    background_color: '#121212',
    theme_color: '#121212',
    icons: [
      { src: '/arix-icon-192.png', sizes: '192x192', type: 'image/png', purpose: 'any' },
      { src: '/arix-icon-512.png', sizes: '512x512', type: 'image/png', purpose: 'any' },
      { src: '/arix-maskable-512.png', sizes: '512x512', type: 'image/png', purpose: 'maskable' },
    ],
  };
}
